-- One-time: the MULTI-MASTER brand (Solutions, Milling) with its uses from
-- the ISCAR intranet e-catalog (Milling), each family linked to its page;
-- families with the same description share a use. An existing MULTI-MASTER is kept:
-- it gets the application, a description if it has none, and the uses it
-- doesn't have (by name).
INSERT INTO "Innovation" ("id", "name", "category", "description")
SELECT 'innovation_multi_master_mill', 'MULTI-MASTER', 'Milling', $u$Interchangeable solid carbide heads on MULTI-MASTER shanks for spot and center drilling, chamfering, countersinking, counterboring and drilling, and for milling: endmill, ball nose, toroidal, barrel, slotting, grooving, thread milling and face milling heads.$u$
WHERE NOT EXISTS (SELECT 1 FROM "Innovation" WHERE upper(regexp_replace("name", '[^A-Za-z0-9]', '', 'g')) = 'MULTIMASTER')
ON CONFLICT DO NOTHING;

UPDATE "Innovation" SET "description" = $u$Interchangeable solid carbide heads on MULTI-MASTER shanks for spot and center drilling, chamfering, countersinking, counterboring and drilling, and for milling: endmill, ball nose, toroidal, barrel, slotting, grooving, thread milling and face milling heads.$u$
WHERE upper(regexp_replace("name", '[^A-Za-z0-9]', '', 'g')) = 'MULTIMASTER' AND ("description" IS NULL OR trim("description") = '');

INSERT INTO "_ApplicationToInnovation" ("A", "B")
SELECT a."id", i."id"
FROM "Application" a, "Innovation" i
WHERE lower(trim(a."name")) = 'milling' AND upper(regexp_replace(i."name", '[^A-Za-z0-9]', '', 'g')) = 'MULTIMASTER'
ON CONFLICT DO NOTHING;

