JOIN "Innovation" i ON upper(regexp_replace(i."name", '[^A-Za-z0-9]', '', 'g')) = 'MULTIMASTER'
WHERE NOT EXISTS (SELECT 1 FROM "InnovationUse" x WHERE x."innovationId" = i."id" AND lower(trim(x."name")) = lower(u."name"))
ON CONFLICT DO NOTHING;

-- MULTI-MASTER is a milling brand too: its description now says so.
UPDATE "Innovation" SET "description" = $u$Interchangeable solid carbide heads on MULTI-MASTER shanks for spot and center drilling, chamfering, countersinking, counterboring and drilling, and for milling: endmill, ball nose, toroidal, barrel, slotting, grooving, thread milling and face milling heads.$u$
WHERE upper(regexp_replace("name", '[^A-Za-z0-9]', '', 'g')) = 'MULTIMASTER'
  AND "description" = $u$Interchangeable solid carbide heads on MULTI-MASTER shanks for spot and center drilling, chamfering, countersinking, counterboring and drilling.$u$;
